alt {
     [] myPort.receive (mw_myMessage) {
       setverdict (pass);
       t_myTimer.start;
       alt {
          [] myPort.receive (mw_mySecondMessage) {
            t_myTimer.stop;
            setverdict (pass);
          }
          [] t_myTimer.timeout {
            myPort.send (m_myRepeat);
            t_myTimer.start;
            alt {
              [] myPort.receive (mw_mySecondMessage) {
                 t_myTimer.stop;
                 setverdict (pass)
              }
              [] t_myTimer.timeout { setverdict (inconc) }
              [] myPort.receive { setverdict (fail) }
            }
          }
          [] myPort.receive { setverdict (fail) }
       }
     }
     [] t_myTimer.timeout { setverdict (inconc) }
     [] myPort.receive { setverdict (fail) }
  }

