// The following TTCN-3 code fragment 
  interleave {
  [] pCO1.receive(mw_mySig1) {
       PCO1.send(m_mySig2);
       PCO1.receive(mw_mySig3);
     }
  [] pCO2.receive(mw_mySig4) {
     pCO2.send(m_mySig5);
     pCO2.send(m_mySig6);
     pCO2.receive(mw_mySig7);
  }
}
// is a shorthand for 
alt {
[] PCO1.receive(mw_mySig1) {
     PCO1.send(m_mySig2);
     alt {
     [] PCO1.receive(mw_mySig3) {
          alt {
          [] PCO2.receive(mw_mySig4) {
              PCO2.send(m_mySig5);
              PCO2.send(m_mySig6);
              PCO2.receive(mw_mySig7)
            }
          }
       }
     [] PCO2.receive(mw_mySig4) {
          PCO2.send(m_mySig5);
          PCO2.send(m_mySig6);
          alt {
          [] PCO1.receive(mw_mySig3) {
              PCO2.receive(mw_mySig7); 
            }
          [] PCO2.receive(mw_mySig7) {
              PCO1.receive(mw_mySig3); 
            }
          }
       }
     }
  }
[] pCO2.receive(mw_mySig4) {
     pCO2.send(m_mySig5);
     pCO2.send(m_mySig6);
     alt {
     [] pCO1.receive(mw_mySig1) {
          pCO1.send(m_mySig2);
          alt {
          [] pCO1.receive(mw_mySig3) {
              pCO2.receive(mw_mySig7);
            }
          [] pCO2.receive(mw_mySig7) {
              pCO1.receive(mw_mySig3);
            }
          }
       }
     [] pCO2.receive(mw_mySig7) {
          alt {
          [] pCO1.receive(mw_mySig1) {
              pCO1.send(m_mySig2);
              pCO1.receive(mw_mySig3);
            }
          }
